{
  "ruleset_id": "additional-education-requirements",
  "rules": [
    {
      "description": "Organization must provide a valid educational license",
      "severity": "critical",
      "category": "license",
      "condition": {"field": "documents.education_license.present", "op": "eq", "value": true}
    },
    {
      "description": "Program volume must be at least 72 hours",
      "severity": "critical",
      "category": "curriculum",
      "condition": {"field": "curriculum.total_hours", "op": "ge", "value": 72}
    },
    {
      "description": "At least 80% of teachers must have relevant qualifications",
      "severity": "major",
      "category": "staff",
      "condition": {"field": "staff.qualified_teachers_pct", "op": "ge", "value": 80}
    },
    {
      "description": "Delivery format must be in-person or mixed only",
      "severity": "critical",
      "category": "delivery",
      "condition": {"field": "programme.delivery_format", "op": "in", "value": ["очно", "смешанно"]}
    }
  ]
}

{
  "ruleset_id": "energy-efficiency-subsidy",
  "rules": [
    {
      "description": "Project must reduce energy consumption by at least 20%",
      "severity": "critical",
      "category": "energy-performance",
      "condition": {"field": "project.energy_consumption_reduction_pct", "op": "ge", "value": 20}
    },
    {
      "description": "Applicant co-financing share must be at least 30%",
      "severity": "critical",
      "category": "budget",
      "condition": {"field": "budget.co_financing_pct", "op": "ge", "value": 30}
    },
    {
      "description": "Technical passport of the object must be provided",
      "severity": "critical",
      "category": "documentation",
      "condition": {"field": "documents.technical_passport.present", "op": "eq", "value": true}
    },
    {
      "description": "Project must be completed no later than December 31, 2027",
      "severity": "critical",
      "category": "timeline",
      "condition": {"field": "project.completion_date", "op": "before", "value": "2027-12-31"}
    }
  ]
}

{
  "ruleset_id": "nordstar-main-track-v2",
  "rules": [
    {
      "description": "Applicant must be registered for at least 24 months to qualify for main track",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "org_v2.months_registered", "op": "ge", "value": 24}
    },
    {
      "description": "Requested grant amount cannot exceed 250,000 euros",
      "severity": "critical",
      "category": "limit",
      "condition": {"field": "org_v2.total_requested", "op": "le", "value": 250000}
    },
    {
      "description": "Independent audit report for last completed financial year must be attached",
      "severity": "critical",
      "category": "required_document",
      "condition": {"field": "documents.audit_report.present", "op": "eq", "value": true}
    },
    {
      "description": "Application must be submitted by March 31, 2027 for 2027 cycle",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "org_v2.submission_date", "op": "before", "value": "2027-03-31"}
    },
    {
      "description": "Declared headcount must match annual report headcount",
      "severity": "major",
      "category": "consistency",
      "condition": {"field": "org_v2.declared_headcount", "op": "consistent", "value": ["annual_report.headcount"]}
    },
    {
      "description": "Annual report must be prepared according to IFRS",
      "severity": "minor",
      "category": "reporting_standard",
      "condition": {"field": "annual_report.ifrs", "op": "eq", "value": true}
    }
  ]
}

{
  "ruleset_id": "primер-грант-2026",
  "rules": [
    {
      "description": "Organization must be registered for at least 12 months",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "application_form.months_registered", "op": "ge", "value": 12}
    },
    {
      "description": "Requested amount cannot exceed 100,000 EUR",
      "severity": "major",
      "category": "budget",
      "condition": {"field": "application_form.requested_total_eur", "op": "le", "value": 100000}
    },
    {
      "description": "Equipment expenses cannot exceed 40% of total budget",
      "severity": "major",
      "category": "budget",
      "condition": {"field": "budget.row.equipment.share_pct", "op": "le", "value": 40}
    },
    {
      "description": "Application form must be present",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.application_form.present", "op": "eq", "value": true}
    },
    {
      "description": "Detailed budget must be present",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.budget.present", "op": "eq", "value": true}
    },
    {
      "description": "Registration certificate must be present",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.registration_cert.present", "op": "eq", "value": true}
    },
    {
      "description": "Financial statement must be present",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.finance_statement.present", "op": "eq", "value": true}
    },
    {
      "description": "Application must be submitted before October 1, 2026",
      "severity": "major",
      "category": "deadline",
      "condition": {"field": "application_form.submission_date", "op": "before", "value": "2026-10-01"}
    },
    {
      "description": "Application form must be signed by legal representative",
      "severity": "critical",
      "category": "signature",
      "condition": {"field": "application_form.signature_present", "op": "eq", "value": true}
    },
    {
      "description": "Requested amount in form must match budget total",
      "severity": "major",
      "category": "consistency",
      "condition": {"field": "application_form.requested_total_eur", "op": "consistent", "value": ["application_form.requested_total_eur", "budget.totals.total"]}
    },
    {
      "description": "Financial statement must cover FY2025",
      "severity": "minor",
      "category": "reporting_period",
      "condition": {"field": "finance_statement.period", "op": "eq", "value": "FY2025"}
    }
  ]
}

{
  "ruleset_id": "kapremont-program",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "building.construction_year", "op": "le", "value": 2005}
    },
    {
      "description": "Решение собственников должно быть поддержано не менее 66% голосов",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "owners.approval_pct", "op": "ge", "value": 66}
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов",
      "severity": "critical",
      "category": "documentation",
      "condition": {"field": "documents.defect_report.present", "op": "eq", "value": true}
    },
    {
      "description": "Заявка должна быть подана до 1 апреля 2027 года включительно",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "application.submission_date", "op": "le", "value": "2027-04-01"}
    }
  ]
}

{
  "ruleset_id": "preferential-microloan-msp",
  "rules": [
    {
      "description": "Annual revenue must not exceed 120,000,000 rubles",
      "severity": "critical",
      "category": "revenue-limit",
      "condition": {"field": "company.annual_revenue_rub", "op": "le", "value": 120000000}
    },
    {
      "description": "No overdue debt may exist",
      "severity": "critical",
      "category": "debt-status",
      "condition": {"field": "company.overdue_debt", "op": "eq", "value": 0}
    },
    {
      "description": "At least 51% ownership must be Russian",
      "severity": "critical",
      "category": "ownership",
      "condition": {"field": "company.russian_ownership_pct", "op": "ge", "value": 51}
    },
    {
      "description": "Requested loan amount must not exceed 10,000,000 rubles",
      "severity": "critical",
      "category": "loan-limit",
      "condition": {"field": "loan.requested_rub", "op": "le", "value": 10000000}
    }
  ]
}

{
  "ruleset_id": "municipal-subsidy-2026",
  "rules": [
    {
      "description": "Applicant must be registered for at least 12 months",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "applicant.registration_months", "op": "ge", "value": 12}
    },
    {
      "description": "Requested subsidy must not exceed 5,000,000 rubles",
      "severity": "critical",
      "category": "limit",
      "condition": {"field": "application.requested_rub", "op": "le", "value": 5000000}
    },
    {
      "description": "Financial statement for the last year must be present",
      "severity": "critical",
      "category": "documentation",
      "condition": {"field": "documents.financial_statement.present", "op": "eq", "value": true}
    },
    {
      "description": "Application must be submitted no later than September 15, 2026",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "application.submission_date", "op": "before", "value": "2026-09-15"}
    },
    {
      "description": "Applicant must not have tax arrears",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "applicant.tax_arrears", "op": "eq", "value": false}
    }
  ]
}

{
  "ruleset_id": "repair-works-procurement-2026",
  "rules": [
    {
      "description": "Annual turnover must be at least 10,000,000 rubles",
      "severity": "critical",
      "category": "financial_capability",
      "condition": {"field": "supplier.annual_turnover_rub", "op": "ge", "value": 10000000}
    },
    {
      "description": "Valid SRO certificate must be present",
      "severity": "critical",
      "category": "certification",
      "condition": {"field": "documents.sro_certificate.present", "op": "eq", "value": true}
    },
    {
      "description": "Sanctions check status must be clear",
      "severity": "critical",
      "category": "sanctions_compliance",
      "condition": {"field": "supplier.sanctions_status", "op": "eq", "value": "clear"}
    },
    {
      "description": "Bid submission deadline is November 20, 2026",
      "severity": "major",
      "category": "submission_timeline",
      "condition": {"field": "bid.submission_date", "op": "le", "value": "2026-11-20"}
    }
  ]
}

{
  "ruleset_id": "applied-research-contest",
  "rules": [
    {
      "description": "Руководитель должен иметь степень кандидат наук или доктор наук",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "researcher.degree", "op": "in", "value": ["кандидат наук", "доктор наук"]}
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "researcher.peer_reviewed_publications", "op": "ge", "value": 3}
    },
    {
      "description": "Необходимо согласие на размещение обезличенных данных исследования",
      "severity": "critical",
      "category": "data_policy",
      "condition": {"field": "documents.open_data_consent.present", "op": "eq", "value": true}
    },
    {
      "description": "Заявленный бюджет должен совпадать с итогом сметы",
      "severity": "critical",
      "category": "budget",
      "condition": {"op": "consistent", "fields": ["application.declared_budget_rub", "budget.total_rub"]}
    }
  ]
}

{
  "ruleset_id": "social-contract-eligibility",
  "rules": [
    {
      "description": "Household must be located in Moscow or Moscow Oblast",
      "severity": "critical",
      "category": "region",
      "condition": {"field": "household.region", "op": "in", "value": ["Moscow", "Moscow Oblast"]}
    },
    {
      "description": "Monthly income per person must not exceed 25000 rubles",
      "severity": "critical",
      "category": "income",
      "condition": {"field": "household.monthly_income_per_person_rub", "op": "le", "value": 25000}
    },
    {
      "description": "Consent for personal data processing must be provided",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.personal_data_consent.present", "op": "eq", "value": true}
    },
    {
      "description": "Applicant must have employment status of unemployed or job_seeker",
      "severity": "critical",
      "category": "employment",
      "condition": {"field": "applicant.employment_status", "op": "in", "value": ["unemployed", "job_seeker"]}
    }
  ]
}
